    a, b = data[0], data[1]
    n, m = len(a), len(b)
    dp = [-1] * (m + 1)
    best_len = n + 1
    best_start = -1
    for i in range(n):
        c = a[i]
        for j in range(m, 0, -1):
            if b[j - 1] == c:
                if j == 1:
                    dp[1] = i
                elif dp[j - 1] != -1:
                    dp[j] = dp[j - 1]
        if dp[m] != -1 and i - dp[m] + 1 < best_len:
            best_len = i - dp[m] + 1
            best_start = dp[m]
    print(a[best_start:best_start + best_len] if best_start != -1 else -1)

