def gen(rng):
    def fmt(a, b):
        return a + '\n' + b

    def rs(n, alpha):
        return ''.join(rng.choice(alpha) for _ in range(n))

    def planted(a, k):
        idx = sorted(rng.sample(range(len(a)), k))
        return ''.join(a[i] for i in idx)

    tests = [fmt('a', 'a'), fmt('a', 'b'), fmt('ab', 'ba'), fmt('abc', 'abc'), fmt('aab', 'ab'), fmt('cba', 'abc'),
             fmt('zzabxcabyc', 'abc'), fmt('abcdebdde', 'bde'), fmt('aaaa', 'aa'), fmt('abab', 'aba'), fmt('a', 'aa'),
             fmt('xyz', 'xyzz')]
    for n in (5, 8, 12, 20, 30, 45):
        for alpha in ('ab', 'abc', 'abcdef'):
            a = rs(n, alpha)
            if rng.random() < 0.7:
                b = planted(a, rng.randint(1, min(5, n)))
            else:
                b = rs(rng.randint(1, 4), alpha)
            tests.append(fmt(a, b))
    N = 10000
    a = rs(N, 'abc')
    tests.append(fmt(a, rs(100, 'abc')))
    a2 = rs(N, 'abcdefghijklmnopqrstuvwxyz')
    tests.append(fmt(a2, planted(a2, 100)))
    tests.append(fmt('a' * N, 'a' * 100))
    tests.append(fmt('ab' * (N // 2), 'ab' * 50))
    tests.append(fmt(rs(N, 'ab'), 'z' + 'a' * 99))
    tests.append(fmt(rs(N, 'abc'), 'c' * 100))
    return tests

